import{_ as t,H as a,f as _,i as s}from"./chunks/framework.BH2BK_3i.js";const l=JSON.parse('{"title":"加餐 | 新型的团队管理和协作方式是怎样的？","description":"","frontmatter":{},"headers":[],"relativePath":"黄勇的OKR实战笔记/加餐-新型的团队管理和协作方式是怎样的？.md","filePath":"黄勇的OKR实战笔记/加餐-新型的团队管理和协作方式是怎样的？.md","lastUpdated":1779822993000}'),n={name:"黄勇的OKR实战笔记/加餐-新型的团队管理和协作方式是怎样的？.md"};function p(i,e,r,o,c,d){return a(),_("div",null,[...e[0]||(e[0]=[s('<h1 id="加餐-新型的团队管理和协作方式是怎样的" tabindex="-1">加餐 | 新型的团队管理和协作方式是怎样的？ <a class="header-anchor" href="#加餐-新型的团队管理和协作方式是怎样的" aria-label="Permalink to &quot;加餐 | 新型的团队管理和协作方式是怎样的？&quot;">​</a></h1><p>你好，我是黄勇。通过对本专栏“OKR 未来展望”模块的学习，希望你能从 OKR 的现在看到 OKR 的未来。</p><p>首先，我们从 OKR 落地失败的一些案例中进行解读，希望你能从这些典型的案例中找出它们失败的原因。随后，为了帮助大家更好地落地 OKR，我从 OKR 的初步落地、初见成效、出具规模等不同阶段，介绍了一些易用且有效 OKR 落地工具。</p><p>接下来，我们一起将视角转到工作之外，结合一个案例来讲解如何在社群中应用 OKR 的实战过程，同时提出了一个如何判断 OKR 是否完备的技巧，即判断 KR 中是否同时具备“引领性指标”和“滞后性指标”，你需要理解引领性指标如何通过杠杆作用去撬动滞后性指标。</p><p>紧接着，我为你介绍了一种新型的团队管理和协同方式，即积分制与游戏化相结合，并通过 OKR 来管理“游戏”目标，让“玩家”在此过程中享受成长和贡献的乐趣。</p><p>在模块最尾部分，我抛出了一些 OKR 无法解决的问题，它并非我们心目中所认为的“银弹”，所以我们应该学会用正确的方法来学习 OKR。</p><p>为了让你更加系统地学习与回顾本模块知识点，以下这份“OKR 技能图谱”希望能够对你有收获和价值。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%BB%84%E5%8B%87%E7%9A%84OKR%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/138383/4919c52939a8daba1221d7e9c8fd2b88.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%BB%84%E5%8B%87%E7%9A%84OKR%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B0/images/138383/4919c52939a8daba1221d7e9c8fd2b88.png" alt=""></a></p><p>（点击图片，长按保存，获取高清长图）</p><p>最后，如果这篇文章让你有所收获，请把它分享给你的朋友，我们一起探讨。</p>',10)])])}const R=t(n,[["render",p]]);export{l as __pageData,R as default};
